export async function capture(db, request) {
  return db.transaction(async (tx) => {
    const previous = await tx.captureByKey(request.idempotencyKey);
    if (previous) return previous;
    await tx.debit(request.account, request.amount);
    return tx.saveCapture(request.idempotencyKey, { ok: true });
  });
}
